'use client'

import type { Metadata } from "next";
import Navbar from "../components/layout/navbar";
import "@styles/theme/main.global.css";
import "@styles/dist/main.global.css";
import "@styles/theme/theme.style.css";
import { ReactLenis } from "@utils/react-lenis";
import PathChecker from "@lib/page-path-checker";
import "boxicons/css/boxicons.min.css";
import { AuthProvider } from "@providers/AuthProvider";
import { ThemeProvider } from "@providers/ThemeProvider";
import { cookies } from "next/headers";
import SideBar from "@components/layout/sidebar";
import SideBarSmall from "@components/layout/sidebar_small";
import { useState } from "react";

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {

  const cookieStore = await cookies();
  const cookieTheme = cookieStore.get("theme")?.value;
  console.log("SSR Theme Cookie:", cookieTheme);
  const darkTheme = cookieTheme === "dark";

  const [expanded, setExpanded] = useState<boolean>(false);

  return (
    <html lang="en">
      <ThemeProvider>
        <AuthProvider>
          <body className={`min-w-[380px] max-w-[2560px] no-underline font-montserrat-sans tracking-letter-spacing-primary shadow-[0_0_50px_0_var(--theme-color-boxShadow-dark)]`}>
            <ReactLenis root options={{
            lerp: 0.1,
            touchMultiplier: 1.25,
          }}>
            <main className={`${darkTheme ? "bg-dark-black-primary text-dark-white-primary" : "bg-light-white-primary text-light-black-primary"}`}>
              <PathChecker />
              <section className="flex h-[100vh] w-[100%]">
                <aside className="max-w-[260px] w-[100%] h-[100vh] z-50 transition-all duration-1000 ease-in-out max-[910px]:absolute max-[910px]:max-w-[unset] max-[910px]:w-[100%] bg-dark-shade-1">
                  <div className={`max-w-[390px] ${expanded ? "w-[100%]" : "w-[60px]"} h-[100vh] transition-all duration-1000 ease-in-out overflow-hidden`}>
                    <SideBar />
                  </div>
                  {/* <div className="max-w-[80px] w-[100%] transform max-[910px]:visible">
                      <SideBarSmall />
                    </div> */}
                </aside>
                <section className="flex flex-col h-[100%] w-full">
                  <nav className={`z-[100] flex justify-center w-[100%] h-[80px]`}>
                    <Navbar />
                  </nav>
                  {children}
                </section>
              </section>
            </main>
            </ReactLenis>
          </body>
        </AuthProvider>
      </ThemeProvider>
    </html>
  );
}
